     * Error are returned as a single element table with 'err' field.
     * Status replies are returned as single element table with 'ok'
     * field. */

    /* Handle error reply. */
    /* we took care of the stack size on function start */
    lua_pushstring(lua,"err");
    lua_rawget(lua,-2);
    t = lua_type(lua,-1);
    if (t == LUA_TSTRING) {
        lua_pop(lua, 1); /* pop the error message, we will use luaExtractErrorInformation to get error information */
        errorInfo err_info = {0};
        luaExtractErrorInformation(lua, &err_info);
        addReplyErrorFormatEx(c,
                              err_info.ignore_err_stats_update? ERR_REPLY_FLAG_NO_STATS_UPDATE: 0,
                              "-%s",
                              err_info.msg);
        luaErrorInformationDiscard(&err_info);
        lua_pop(lua,1); /* pop the result table */
        return;
    }
    lua_pop(lua,1); /* Discard field name pushed before. */

    /* Handle status reply. */
    lua_pushstring(lua,"ok");
    lua_rawget(lua,-2);
    t = lua_type(lua,-1);
    if (t == LUA_TSTRING) {
        sds ok = sdsnew(lua_tostring(lua,-1));
        sdsmapchars(ok,"\r\n","  ",2);
        addReplyStatusLength(c, ok, sdslen(ok));
        sdsfree(ok);
        lua_pop(lua,2);
        return;
    }
    lua_pop(lua,1); /* Discard field name pushed before. */

    /* Handle double reply. */
    lua_pushstring(lua,"double");
    lua_rawget(lua,-2);
    t = lua_type(lua,-1);
    if (t == LUA_TNUMBER) {
        addReplyDouble(c,lua_tonumber(lua,-1));
        lua_pop(lua,2);
        return;
    }
    lua_pop(lua,1); /* Discard field name pushed before. */

    /* Handle big number reply. */
    lua_pushstring(lua,"big_number");
    lua_rawget(lua,-2);
    t = lua_type(lua,-1);
    if (t == LUA_TSTRING) {
        sds big_num = sdsnewlen(lua_tostring(lua,-1), lua_strlen(lua,-1));
        sdsmapchars(big_num,"\r\n","  ",2);
        addReplyBigNum(c,big_num,sdslen(big_num));
        sdsfree(big_num);
        lua_pop(lua,2);
        return;
    }
    lua_pop(lua,1); /* Discard field name pushed before. */

    /* Handle verbatim reply. */
    lua_pushstring(lua,"verbatim_string");
    lua_rawget(lua,-2);
    t = lua_type(lua,-1);
    if (t == LUA_TTABLE) {
        lua_pushstring(lua,"format");
