                addReplyVerbatim(c, str, len, format);
                lua_pop(lua,4);
                return;
            }
            lua_pop(lua,1);
        }
        lua_pop(lua,1);
    }
    lua_pop(lua,1); /* Discard field name pushed before. */

    /* Handle map reply. */
    lua_pushstring(lua,"map");
    lua_rawget(lua,-2);
    t = lua_type(lua,-1);
