void freeLuaRedisArgv(robj **argv, int argc, int argv_len);

/* Cached argv array across calls. */
static robj **lua_argv = NULL;
static int lua_argv_size = 0;

/* Cache of recently used small arguments to avoid malloc calls. */
static robj *lua_args_cached_objects[LUA_CMD_OBJCACHE_SIZE];
static size_t lua_args_cached_objects_len[LUA_CMD_OBJCACHE_SIZE];

/* Convert Lua redis.call/pcall arguments into Redis argv objects.
 * This lives with the generic script run context so both EVAL and Functions
 * can reuse the same conversion, while still consulting the Lua stack, the
 * script client, cached robj/SDS payloads, and the original caller. */
robj **luaArgsToRedisArgv(scriptRunCtx *run_ctx, lua_State *lua, int *argc, int *argv_len) {
    int j;
    client *script_client = run_ctx->c;
    client *caller = run_ctx->original_client;

    /* Require at least one argument */
    *argc = lua_gettop(lua);
    if (*argc == 0) {
        luaPushError(lua, "Please specify at least one argument for this redis lib call");
        return NULL;
    }

    /* Build the arguments vector (reuse a cached argv from last call) */
    if (lua_argv_size < *argc) {
        lua_argv = zrealloc(lua_argv,sizeof(robj*)* *argc);
        lua_argv_size = *argc;
    }
    *argv_len = lua_argv_size;

    for (j = 0; j < *argc; j++) {
        char *obj_s;
        size_t obj_len;
        char dbuf[64];

        if (lua_type(lua,j+1) == LUA_TNUMBER) {
            /* We can't use lua_tolstring() for number -> string conversion
             * since Lua uses a format specifier that loses precision. */
            lua_Number num = lua_tonumber(lua,j+1);
            obj_len = fpconv_dtoa((double)num, dbuf);
            dbuf[obj_len] = '\0';
            obj_s = dbuf;
        } else {
            obj_s = (char*)lua_tolstring(lua,j+1,&obj_len);
            if (obj_s == NULL) break; /* Not a string. */
        }
        /* Try to use a cached object. Cached entries are exclusive SDS
         * strings; inspect the robj and SDS header to confirm the payload
         * can be overwritten in place. */
        robj *cached = (j < LUA_CMD_OBJCACHE_SIZE) ? lua_args_cached_objects[j] : NULL;
        if (cached &&
            cached->refcount == 1 &&
            (cached->encoding == OBJ_ENCODING_RAW ||
             cached->encoding == OBJ_ENCODING_EMBSTR) &&
            lua_args_cached_objects_len[j] >= obj_len)
        {
            sds s = cached->ptr;
            unsigned char hdr_flags = s[-1];
            struct sdshdr8 *sh = SDS_HDR(8, s);
            size_t cached_alloc = ((hdr_flags & SDS_TYPE_MASK) == SDS_TYPE_8)
                ? sh->alloc : sdsalloc(s);
            if (cached_alloc >= obj_len) {
                lua_argv[j] = cached;
                lua_args_cached_objects[j] = NULL;
                memcpy(s,obj_s,obj_len+1);
                if ((hdr_flags & SDS_TYPE_MASK) == SDS_TYPE_8)
                    sh->len = obj_len;
                else
                    sdssetlen(s, obj_len);
            } else {
                lua_argv[j] = createStringObject(obj_s, obj_len);
            }
        } else {
            lua_argv[j] = createStringObject(obj_s, obj_len);
        }
    }

    /* Pop all arguments from the stack, we do not need them anymore
     * and this way we guaranty we will have room on the stack for the result. */
    lua_pop(lua, *argc);

    /* Check if one of the arguments passed by the Lua script
     * is not a string or an integer (lua_isstring() return true for
     * integers as well). */
    if (j != *argc) {
        freeLuaRedisArgv(lua_argv, j, lua_argv_size);
        luaPushError(lua, "Lua redis lib command arguments must be strings or integers");
        return NULL;
    }

    /* Install the converted argv on the script client and attribute it to
     * the original caller before the command is executed. */
    script_client->argv = lua_argv;
    script_client->argc = *argc;
    script_client->argv_len = lua_argv_size;
    script_client->user = caller->user;
    return lua_argv;
}

